<?php
defined('ABSPATH') || exit;
final class MUTQAN_Financial_Reports {
 public static function init(){add_action('rest_api_init',array(__CLASS__,'rest'));}
 private static function manage(){return current_user_can('mutqan_manage_operations')||current_user_can('mutqan_manage_settings')||current_user_can('mutqan_view_audit');}
 public static function rest(){register_rest_route('mutqan/v1','/finance/reports/summary',array('methods'=>WP_REST_Server::READABLE,'permission_callback'=>function(){return self::manage();},'callback'=>function($r){global $wpdb;$from=sanitize_text_field($r->get_param('from')?:gmdate('Y-m-01'));$to=sanitize_text_field($r->get_param('to')?:gmdate('Y-m-d'));$inv=$wpdb->get_row($wpdb->prepare("SELECT COALESCE(SUM(total),0) revenue,COALESCE(SUM(discount),0) discounts,COALESCE(SUM(tax),0) tax FROM ".MUTQAN_Billing::table()." WHERE created_at BETWEEN %s AND %s",$from.' 00:00:00',$to.' 23:59:59'),ARRAY_A);$paid=$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(total),0) FROM ".MUTQAN_Billing::table()." WHERE payment_status='paid' AND created_at BETWEEN %s AND %s",$from.' 00:00:00',$to.' 23:59:59'));$comm=$wpdb->get_row($wpdb->prepare("SELECT COALESCE(SUM(commission_amount),0) total,COUNT(*) count FROM ".MUTQAN_Commissions::ledger()." WHERE created_at BETWEEN %s AND %s",$from.' 00:00:00',$to.' 23:59:59'),ARRAY_A);$wallet=$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(amount),0) FROM ".MUTQAN_Wallets::tx_table()." WHERE type='topup' AND created_at BETWEEN %s AND %s",$from.' 00:00:00',$to.' 23:59:59'));return rest_ensure_response(array('from'=>$from,'to'=>$to,'revenue'=>(float)$inv['revenue'],'paid'=>(float)$paid,'discounts'=>(float)$inv['discounts'],'tax'=>(float)$inv['tax'],'technician_commissions'=>(float)$comm['total'],'commission_count'=>(int)$comm['count'],'wallet_topups'=>(float)$wallet));}));}
}
MUTQAN_Financial_Reports::init();
